#include <cstdlib>

class Solution {
public:
    int findClosest(int x, int y, int z) {
        int dx = std::abs(x - z);
        int dy = std::abs(y - z);
        if (dx < dy) return 1;
        if (dy < dx) return 2;
        return 0;
    }
};

class Solution {
    public int findClosest(int x, int y, int z) {
        int dx = Math.abs(x - z);
        int dy = Math.abs(y - z);
        if (dx < dy) return 1;
        if (dy < dx) return 2;
        return 0;
    }
}

var findClosest = function(x, y, z) {
    const dx = Math.abs(x - z);
    const dy = Math.abs(y - z);
    if (dx < dy) return 1;
    if (dy < dx) return 2;
    return 0;
};
